import type { On } from 'claude-code'

/**
 * Empties the dim hint line under the prompt. The permission mode badge
 * beside it is drawn by the engine outside PromptHint and stays.
 */
export function register(on: On) {
  on('ui.render', { component: 'PromptHint' }, ($, e, next) => next({ ...e, props: { ...e.props, hint: '' } }))
}

